  `select count(*)::text as count from usage
   where org_id = $1 and created_at >= $2
     and (status = 'recorded' or (status = 'reserved' and created_at >= $3))`,
  [orgId, monthStart.toISOString(), cutoff.toISOString()],
);

mutations.after:
